using UnityEngine;

public class PlayerMovement : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float jumpForce = 10f;

    private Rigidbody rb;
    private Transform cachedTransform;
    private bool isGrounded;

    // Awake: Initialize self-references ONLY
    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        cachedTransform = transform; // Cache transform reference

        if (rb == null)
        {
            Debug.LogError("[PlayerMovement] Rigidbody missing!");
            enabled = false;
        }
    }

    // Start: Cross-object initialization (safe here)
    private void Start()
    {
        // Safe to find other objects now
        GameManager.Instance.RegisterPlayer(this);
    }

    // FixedUpdate: Physics logic at fixed timestep
    private void FixedUpdate()
    {
        HandleMovement();
        HandleJump();
    }

    private void HandleMovement()
    {
        float horizontal = Input.GetAxis("Horizontal");
        float vertical = Input.GetAxis("Vertical");

        Vector3 movement = new Vector3(horizontal, 0f, vertical) * moveSpeed;
        rb.velocity = new Vector3(movement.x, rb.velocity.y, movement.z);
    }

    private void HandleJump()
    {
        if (Input.GetButtonDown("Jump") && isGrounded)
        {
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
        }
    }

    private void OnCollisionEnter(Collision collision)
    {
        if (collision.gameObject.CompareTag("Ground"))
        {
            isGrounded = true;
        }
    }

    private void OnCollisionExit(Collision collision)
    {
        if (collision.gameObject.CompareTag("Ground"))
        {
            isGrounded = false;
        }
    }
}

