[CreateAssetMenu(fileName = "SO_ShotgunStrategy", menuName = "Weapons/Shotgun")]
public class ShotgunStrategy : WeaponStrategy
{
    [SerializeField] private float _damagePerPellet = 8f;
    [SerializeField] private float _cooldown = 0.8f;
    [SerializeField] private int _pelletCount = 8;
    [SerializeField] private float _spreadAngle = 15f;
    [SerializeField] private float _range = 20f;
    [SerializeField] private LayerMask _hitLayers;
    public override float Damage => _damagePerPellet * _pelletCount;
    public override float Cooldown => _cooldown;
