public class DrawCallOptimizer : MonoBehaviour
{
    [Header("Batching Test")]
    [SerializeField] private GameObject _prefab;
    [SerializeField] private int _count = 100;
    [SerializeField] private bool _useSharedMaterial;
    [SerializeField] private bool _useStaticBatching;
    [SerializeField] private bool _useGPUInstancing;

    private void Start()
    {
        for (int i = 0; i < _count; i++)
        {
            Vector3 pos = new Vector3(i % 10, 0, i / 10);
            GameObject go = Instantiate(_prefab, pos, Quaternion.identity);

            if (_useSharedMaterial)
            {
                // All objects share one material = one batch
                go.GetComponent<Renderer>().sharedMaterial = _prefab.GetComponent<Renderer>().sharedMaterial;
            }
            else if (_useGPUInstancing)
            {
                // GPU Instancing: one draw call for all identical meshes/materials
                Material mat = go.GetComponent<Renderer>().material;
                mat.enableInstancing = true;
            }

            if (_useStaticBatching)
            {
                go.isStatic = true;
            }
        }

        if (_useStaticBatching)
        {
            // Static batching requires a batching trigger
            StaticBatchingUtility.Combine(gameObject.scene);
        }
    }
}

using UnityEngine;

public class BatchingComparison : MonoBehaviour
{
    // Static Batching: Best for environment geometry (walls, floors, props)
    // Requirements: Objects marked as Static, same material, built at compile time
    // Trade-off: Higher memory usage (combined mesh stored in memory)

    // Dynamic Batching: Best for small moving objects (particles, debris)
    // Requirements: <300 vertices, same material, transforms change every frame
    // Trade-off: CPU cost to rebuild batches each frame

    // GPU Instancing: Best for repeated objects (trees, enemies, bullets)
    // Requirements: Identical mesh + material, material.enableInstancing = true
    // Trade-off: Shader must support instancing; limited per-instance data

    [SerializeField] private Material _instancedMaterial;
    [SerializeField] private Mesh _instanceMesh;
    [SerializeField] private int _instanceCount = 1000;
    private Matrix4x4[] _matrices;

    private void Start()
    {
        _matrices = new Matrix4x4[_instanceCount];
        for (int i = 0; i < _instanceCount; i++)
        {
            Vector3 pos = new Vector3(i % 50, 0, i / 50);
            _matrices[i] = Matrix4x4.TRS(pos, Quaternion.identity, Vector3.one);
        }
    }

    private void Update()
    {
        // Manual GPU instancing via Graphics.DrawMeshInstanced
        // Zero GameObjects = zero component overhead
        Graphics.DrawMeshInstanced(_instanceMesh, 0, _instancedMaterial, _matrices, _instanceCount);
    }
}

