public class MemoryLeakFixes : MonoBehaviour
{
    // LEAK: Static list grows forever
    // private static List<Texture2D> _loadedTextures = new List<Texture2D>();

    // FIX: Use a dictionary with cleanup, or Addressables with release
    private static readonly Dictionary<string, Texture2D> _textureCache = new Dictionary<string, Texture2D>();
    private static readonly int MAX_CACHE_SIZE = 50;

    public static Texture2D LoadTexture(string path)
    {
        if (_textureCache.TryGetValue(path, out Texture2D cached))
        {
            return cached;
        }

        // Load and cache with size limit
        Texture2D tex = Resources.Load<Texture2D>(path);
        if (_textureCache.Count >= MAX_CACHE_SIZE)
        {
            // Remove oldest entry (simple LRU approximation)
            foreach (var key in _textureCache.Keys)
            {
                _textureCache.Remove(key);
                break;
            }
        }
        _textureCache[path] = tex;
        return tex;
    }

    // LEAK: Event subscription without unsubscription
    // private void OnEnable() => EventManager.Instance.Subscribe<SomeEvent>(Handler);
    // // Missing OnDisable!

    // FIX: Always unsubscribe
    private void OnEnable() => EventManager.Instance.Subscribe<GameOverEvent>(OnGameOver);
    private void OnDisable() => EventManager.Instance.Unsubscribe<GameOverEvent>(OnGameOver);
    private void OnGameOver(GameOverEvent evt) { /* Handle */ }

    // LEAK: Coroutines running on destroyed objects
    // private IEnumerator LongCoroutine() { yield return new WaitForSeconds(60f); }

    // FIX: Stop coroutines in OnDestroy or use cancellation tokens
    private System.Threading.CancellationTokenSource _cts;
    private async void StartLongOperation()
    {
        _cts = new System.Threading.CancellationTokenSource();
        try
        {
            await System.Threading.Tasks.Task.Delay(60000, _cts.Token);
        }
        catch (System.OperationCanceledException)
        {
            Debug.Log("Operation cancelled cleanly.");
        }
    }

    private void OnDestroy() => _cts?.Cancel();
}

