using UnityEngine;
using System.Collections.Generic;

public interface IPoolable
{
    void OnSpawn();
    void OnDespawn();
}

public class ObjectPool<T> where T : Component, IPoolable
{
    private readonly T _prefab;
    private readonly Transform _parent;
    private readonly Queue<T> _pool;
    private readonly List<T> _active;
    private readonly int _initialSize;
    private readonly int _maxSize;

    public ObjectPool(T prefab, Transform parent, int initialSize = 50, int maxSize = 500)
    {
        _prefab = prefab;
        _parent = parent;
        _initialSize = initialSize;
        _maxSize = maxSize;
        _pool = new Queue<T>(initialSize);
        _active = new List<T>(initialSize);
        PreWarm();
    }

    private void PreWarm()
    {
        for (int i = 0; i < _initialSize; i++)
        {
            T instance = CreateInstance();
            instance.gameObject.SetActive(false);
            _pool.Enqueue(instance);
        }
    }

    private T CreateInstance()
    {
        T instance = Object.Instantiate(_prefab, _parent);
        instance.name = $"{_prefab.name}_{_pool.Count + _active.Count}";
        return instance;
    }

    public T Get()
    {
        T instance;
        if (_pool.Count > 0)
        {
            instance = _pool.Dequeue();
        }
        else if (_active.Count < _maxSize)
        {
            instance = CreateInstance();
        }
        else
        {
            Debug.LogWarning($"Pool for {_prefab.name} at max capacity ({_maxSize}). Reusing oldest active.");
            instance = _active[0];
            _active.RemoveAt(0);
            instance.OnDespawn();
        }

        instance.gameObject.SetActive(true);
        instance.OnSpawn();
        _active.Add(instance);
        return instance;
    }

    public void Return(T instance)
    {
        if (!_active.Contains(instance)) return;

        instance.OnDespawn();
        instance.gameObject.SetActive(false);
        _active.Remove(instance);
        _pool.Enqueue(instance);
    }

    public void ReturnAll()
    {
        for (int i = _active.Count - 1; i >= 0; i--)
        {
            Return(_active[i]);
        }
    }

    public int ActiveCount => _active.Count;
    public int InactiveCount => _pool.Count;
}

