using UnityEngine;

public class PreAllocatedBuffer<T> where T : struct
{
    private readonly T[] _buffer;
    private int _count;

    public PreAllocatedBuffer(int maxCapacity)
    {
        _buffer = new T[maxCapacity];
        _count = 0;
    }

    public int Count => _count;
    public int Capacity => _buffer.Length;
    public T[] RawArray => _buffer; // For NativeArray copy

    public void Add(ref T item)
    {
        if (_count >= _buffer.Length)
        {
            Debug.LogWarning($"PreAllocatedBuffer overflow! Max: {_buffer.Length}");
            return;
        }
        _buffer[_count++] = item;
    }

    public void Clear() => _count = 0;
    public T this[int index] => _buffer[index];

    // Zero-allocation iteration
    public void ForEach(System.Action<T> action)
    {
        for (int i = 0; i < _count; i++)
        {
            action(_buffer[i]);
        }
    }
}

