using UnityEngine;
using Unity.Collections;
using Unity.Jobs;

public class JobSafetyRules : MonoBehaviour
{
    // RULE 1: Only blittable types in jobs
    // BAD: public string Name; // String is a reference type!
    // GOOD: public NativeArray<char> Name; // Or use fixed buffers

    // RULE 2: Mark read-only data to allow parallel reading
    struct SafeJob : IJobParallelFor
    {
        [ReadOnly] public NativeArray<int> ReadOnlyData; // Multiple threads can read
        [WriteOnly] public NativeArray<int> WriteOnlyData; // Each index written once
        // [NativeDisableParallelForRestriction] public NativeArray<int> ReadWriteData; // Use with caution

        public void Execute(int index)
        {
            WriteOnlyData[index] = ReadOnlyData[index] * 2;
        }
    }

    // RULE 3: Always dispose NativeArrays
    private NativeArray<int> _data;
    private void Awake() => _data = new NativeArray<int>(100, Allocator.Persistent);
    private void OnDestroy() => _data.Dispose(); // NEVER forget this!

    // RULE 4: Use JobHandle dependencies for ordering
    private void ChainedJobs()
    {
        NativeArray<int> array = new NativeArray<int>(100, Allocator.TempJob);

        JobA jobA = new JobA { Data = array };
        JobHandle handleA = jobA.Schedule(100, 32);

        JobB jobB = new JobB { Data = array };
        JobHandle handleB = jobB.Schedule(100, 32, handleA); // Depends on A

        handleB.Complete(); // Waits for both A and B
        array.Dispose();
    }

    struct JobA : IJobParallelFor { public NativeArray<int> Data; public void Execute(int i) => Data[i] = i; }
    struct JobB : IJobParallelFor { [ReadOnly] public NativeArray<int> Data; public void Execute(int i) { /* reads Data[i] */ } }
}

using UnityEngine;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;
using Unity.Burst;

public class BurstCompilerDemo : MonoBehaviour
{
    [SerializeField] private int _particleCount = 10000;
    private NativeArray<float3> _positions;
    private NativeArray<float3> _velocities;

    private void Start()
    {
        _positions = new NativeArray<float3>(_particleCount, Allocator.Persistent);
        _velocities = new NativeArray<float3>(_particleCount, Allocator.Persistent);

        for (int i = 0; i < _particleCount; i++)
        {
            _positions[i] = new float3(UnityEngine.Random.Range(-100f, 100f), 0, UnityEngine.Random.Range(-100f, 100f));
            _velocities[i] = new float3(UnityEngine.Random.Range(-1f, 1f), 0, UnityEngine.Random.Range(-1f, 1f));
        }
    }

    private void Update()
    {
        // WITHOUT Burst: Mono JIT compilation, no vectorization
        // WITH Burst: LLVM native compilation, SIMD vectorization
        ParticleMoveJob moveJob = new ParticleMoveJob
        {
            Positions = _positions,
            Velocities = _velocities,
            DeltaTime = Time.deltaTime,
            Bounds = 100f
        };

        JobHandle handle = moveJob.Schedule(_particleCount, 64);
        handle.Complete();
    }

    private void OnDestroy()
    {
        _positions.Dispose();
        _velocities.Dispose();
    }

    [BurstCompile(FloatMode = FloatMode.Fast, FloatPrecision = FloatPrecision.Standard, CompileSynchronously = false)]
    struct ParticleMoveJob : IJobParallelFor
    {
        [NativeDisableParallelForRestriction]
        public NativeArray<float3> Positions;

        [ReadOnly]
        public NativeArray<float3> Velocities;

        public float DeltaTime;
        public float Bounds;

        public void Execute(int index)
        {
            float3 pos = Positions[index];
            float3 vel = Velocities[index];

            // Burst vectorizes this math automatically
            pos += vel * DeltaTime;

            // Bounce off boundaries using math library
            if (math.abs(pos.x) > Bounds) vel.x = -vel.x;
            if (math.abs(pos.z) > Bounds) vel.z = -vel.z;

            // Clamp position
            pos = math.clamp(pos, new float3(-Bounds, 0, -Bounds), new float3(Bounds, 0, Bounds));

            Positions[index] = pos;
        }
    }
}

using UnityEngine;
using Unity.Mathematics;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;

public class MathematicsLibrary : MonoBehaviour
{
    // UnityEngine.Vector3 vs Unity.Mathematics.float3 comparison

    // BAD for Burst: UnityEngine types (classes, properties, non-blittable)
    // Vector3 pos = transform.position; // Burst cannot optimize this
    // float dist = Vector3.Distance(a, b); // Not vectorizable

    // GOOD for Burst: Mathematics types (structs, fields, SIMD-friendly)
    // float3 pos = new float3(1, 2, 3);
    // float dist = math.distance(a, b); // Maps to SIMD sqrt

    [BurstCompile]
    struct MathComparisonJob : IJobParallelFor
    {
        [ReadOnly] public NativeArray<float3> PositionsA;
        [ReadOnly] public NativeArray<float3> PositionsB;
        [WriteOnly] public NativeArray<float> Distances;
        [WriteOnly] public NativeArray<float3> Directions;

        public void Execute(int index)
        {
            float3 a = PositionsA[index];
            float3 b = PositionsB[index];

            // SIMD-vectorized math operations
            float3 diff = b - a;
            float sqrLen = math.lengthsq(diff); // x*x + y*y + z*z (SIMD)
            float dist = math.sqrt(sqrLen);     // SIMD sqrt instruction
            float3 dir = math.normalize(diff);  // SIMD division + sqrt

            // Trigonometry: SIMD sin/cos
            float angle = math.atan2(dir.z, dir.x);
            float sinAngle = math.sin(angle);
            float cosAngle = math.cos(angle);

            // Matrix operations for rotation
            float3x3 rotMatrix = math.float3x3(
                cosAngle, 0, -sinAngle,
                0, 1, 0,
                sinAngle, 0, cosAngle
            );
            float3 rotated = math.mul(rotMatrix, dir);

            Distances[index] = dist;
            Directions[index] = rotated;
        }
    }

    // Common math library replacements
    private void MathCheatSheet()
    {
        float3 a = new float3(1, 2, 3);
        float3 b = new float3(4, 5, 6);

        float dot = math.dot(a, b);           // Was: Vector3.Dot
        float3 cross = math.cross(a, b);      // Was: Vector3.Cross
        float dist = math.distance(a, b);     // Was: Vector3.Distance
        float3 lerp = math.lerp(a, b, 0.5f); // Was: Vector3.Lerp
        float3 norm = math.normalize(a);      // Was: a.normalized
        float len = math.length(a);           // Was: a.magnitude
        float sqrLen = math.lengthsq(a);      // Was: a.sqrMagnitude
        float3 clamped = math.clamp(a, 0, 10); // Was: Vector3.Min/Max
        float3 reflect = math.reflect(a, b);  // Reflection vector
        float3 project = math.project(a, b);  // Projection of a onto b

        // Random: Burst-compatible deterministic random
        Random random = new Random(12345); // Seed
        float randFloat = random.NextFloat(0, 1);
        float3 randDir = random.NextFloat3Direction();

        // Noise: SIMD-optimized Perlin/Simplex noise
        float noise2D = noise.snoise(new float2(1, 2));
        float noise3D = noise.snoise(new float3(1, 2, 3));
    }
}

using Unity.Burst;
using Unity.Jobs;
using Unity.Collections;

public class BurstOptionsDemo
{
    // Precision-critical: Physics simulation, networking prediction
    [BurstCompile(FloatMode = FloatMode.Strict, FloatPrecision = FloatPrecision.High)]
    struct PhysicsJob : IJobParallelFor
    {
        [ReadOnly] public NativeArray<float> Masses;
        public NativeArray<float3> Velocities;
        public float DeltaTime;

        public void Execute(int index)
        {
            // Strict mode: exact operation order, no reassociation
            // High precision: double-precision intermediates where needed
            float3 force = new float3(0, -9.81f * Masses[index], 0);
            float3 acceleration = force / Masses[index];
            Velocities[index] += acceleration * DeltaTime;
        }
    }

    // Performance-critical: Particle effects, visual-only calculations
    [BurstCompile(FloatMode = FloatMode.Fast, FloatPrecision = FloatPrecision.Standard)]
    struct VisualEffectJob : IJobParallelFor
    {
        public NativeArray<float3> Positions;
        [ReadOnly] public NativeArray<float3> Velocities;
        public float DeltaTime;

        public void Execute(int index)
        {
            // Fast mode: allows (a+b)+c → a+(b+c) reordering for SIMD
            // Standard precision: float32 throughout
            Positions[index] += Velocities[index] * DeltaTime;
        }
    }

    // Release-only: Maximum speed, no safety nets
    // [BurstCompile(FloatMode = FloatMode.Fast, CompileSynchronously = false, DisableSafetyChecks = true)]
    // struct ReleaseJob : IJobParallelFor { /* ... */ }
    // WARNING: Only use DisableSafetyChecks after EXTENSIVE testing!
}

using UnityEngine;

public class BatchingManager : MonoBehaviour
{
    [Header("Batching Test Setup")]
    [SerializeField] private GameObject _staticPrefab;
    [SerializeField] private GameObject _dynamicPrefab;
    [SerializeField] private GameObject _instancedPrefab;
    [SerializeField] private Material _instancedMaterial;
    [SerializeField] private int _instanceCount = 1000;

    private void Start()
    {
        // STATIC BATCHING: Mark objects as static, Unity combines at build
        for (int i = 0; i < 100; i++)
        {
            Vector3 pos = new Vector3(i * 2f, 0, 0);
            GameObject go = Instantiate(_staticPrefab, pos, Quaternion.identity);
            go.isStatic = true; // CRITICAL: Mark as static for batching
            // All static objects with same material become one draw call
        }

        // DYNAMIC BATCHING: Small moving objects (<300 vertices) auto-batched
        for (int i = 0; i < 50; i++)
        {
            Vector3 pos = new Vector3(i * 0.5f, 1f, 0);
            GameObject go = Instantiate(_dynamicPrefab, pos, Quaternion.identity);
            // Must be <300 vertices and use same material
            // Unity rebuilds batch every frame — CPU cost
        }

        // GPU INSTANCING: Identical mesh+material, thousands of copies
        _instancedMaterial.enableInstancing = true; // Enable in material
        for (int i = 0; i < _instanceCount; i++)
        {
            Vector3 pos = new Vector3(
                Mathf.Sin(i * 0.1f) * 20f, 
                Mathf.Cos(i * 0.1f) * 20f, 
                0
            );
            GameObject go = Instantiate(_instancedPrefab, pos, Quaternion.identity);
            go.GetComponent<Renderer>().sharedMaterial = _instancedMaterial;
            // All 1000 objects = 1 draw call (if shader supports instancing)
        }
    }

    // MANUAL GPU INSTANCING: Zero GameObjects, maximum performance
    private Matrix4x4[] _instanceMatrices;
    private Mesh _instanceMesh;

    private void SetupManualInstancing()
    {
        _instanceMatrices = new Matrix4x4[_instanceCount];
        _instanceMesh = _instancedPrefab.GetComponent<MeshFilter>().sharedMesh;

        for (int i = 0; i < _instanceCount; i++)
        {
            Vector3 pos = new Vector3(i % 50, 0, i / 50);
            _instanceMatrices[i] = Matrix4x4.TRS(pos, Quaternion.identity, Vector3.one);
        }
    }

    private void Update()
    {
        // Manual instancing: 1 draw call, zero Transform overhead
        if (_instanceMatrices != null)
        {
            Graphics.DrawMeshInstanced(
                _instanceMesh, 
                0, 
                _instancedMaterial, 
                _instanceMatrices, 
                _instanceCount
            );
        }
    }

    // SRP Batcher: For URP/HDRP, reduces material setup cost
    // No code needed — automatic when using SRP + compatible shaders
    // Check: Frame Debugger shows "SRP Batcher" instead of individual draw calls
}

