using UnityEngine;
using UnityEngine.Rendering;

public class SRPBatcherCheck : MonoBehaviour
{
    [Header("SRP Batcher Diagnostics")]
    [SerializeField] private bool _showBatcherStats = true;

    private void OnGUI()
    {
        if (!_showBatcherStats) return;

        // Check if SRP Batcher is enabled
        bool srpBatcherEnabled = GraphicsSettings.useScriptableRenderPipelineBatching;

        GUILayout.Label($"SRP Batcher Enabled: {srpBatcherEnabled}");

        if (srpBatcherEnabled)
        {
            // SRP Batcher stats (available in URP/HDRP)
            // Frame Debugger shows "SRP Batcher" label on compatible draw calls
            GUILayout.Label("Check Frame Debugger for 'SRP Batcher' labels");
            GUILayout.Label("Compatible: Same shader variant, different properties");
            GUILayout.Label("Incompatible: Different shaders, multi-pass, material property blocks");
        }
        else
               {
            GUILayout.Label("WARNING: SRP Batcher disabled! Enable in URP/HDRP asset.");
        }
    }

    // Force SRP Batcher compatibility check on materials
    private void ValidateMaterials()
    {
        Renderer[] renderers = FindObjectsOfType<Renderer>();
        int compatibleCount = 0;
        int incompatibleCount = 0;

        foreach (var renderer in renderers)
        {
            Material mat = renderer.sharedMaterial;
            if (mat != null && mat.shader.isSupported)
            {
                // Check shader compatibility
                bool isSRP = GraphicsSettings.currentRenderPipeline != null;
                if (isSRP && mat.enableInstancing)
                {
                    compatibleCount++;
                }
                else
                {
                    incompatibleCount++;
                    Debug.LogWarning($"Incompatible material: {mat.name} on {renderer.name}");
                }
            }
        }

        Debug.Log($"SRP Batcher: {compatibleCount} compatible, {incompatibleCount} incompatible materials");
    }
}

