[RequireComponent(typeof(LODGroup))]
public class LODSetup : MonoBehaviour
{
    [Header("LOD Meshes")]
    [SerializeField] private Mesh _lod0Mesh; // 5000 triangles, close up
    [SerializeField] private Mesh _lod1Mesh; // 2500 triangles, medium
    [SerializeField] private Mesh _lod2Mesh; // 800 triangles, far
    [SerializeField] private Mesh _lod3Mesh; // 200 triangles or billboard, very far

    [Header("LOD Materials")]
    [SerializeField] private Material _lod0Material; // Full PBR
    [SerializeField] private Material _lod1Material; // Simplified PBR
    [SerializeField] private Material _lod2Material; // Unlit or simple diffuse
    [SerializeField] private Material _lod3Material; // Billboard or transparent

    [Header("LOD Settings")]
    [SerializeField, Range(0.01f, 1f)] private float _lod0ScreenPercent = 0.6f;
    [SerializeField, Range(0.01f, 1f)] private float _lod1ScreenPercent = 0.3f;
    [SerializeField, Range(0.01f, 1f)] private float _lod2ScreenPercent = 0.1f;
    [SerializeField, Range(0.01f, 1f)] private float _lod3ScreenPercent = 0.05f;
    [SerializeField] private float _fadeTransitionWidth = 0.1f;

    private void Awake()
    {
        LODGroup lodGroup = GetComponent<LODGroup>();

        // Create LOD levels programmatically
        LOD[] lods = new LOD[4];

        // LOD0: Full detail, 60% screen space
        Renderer[] lod0Renderers = CreateLODRenderers(_lod0Mesh, _lod0Material);
        lods[0] = new LOD(_lod0ScreenPercent, lod0Renderers);

        // LOD1: Medium detail, 30% screen space
        Renderer[] lod1Renderers = CreateLODRenderers(_lod1Mesh, _lod1Material);
        lods[1] = new LOD(_lod1ScreenPercent, lod1Renderers);

        // LOD2: Low detail, 10% screen space
        Renderer[] lod2Renderers = CreateLODRenderers(_lod2Mesh, _lod2Material);
        lods[2] = new LOD(_lod2ScreenPercent, lod2Renderers);

        // LOD3: Ultra low, 5% screen space (culled below this)
        Renderer[] lod3Renderers = CreateLODRenderers(_lod3Mesh, _lod3Material);
        lods[3] = new LOD(_lod3ScreenPercent, lod3Renderers);

        lodGroup.SetLODs(lods);
        lodGroup.fadeMode = LODFadeMode.CrossFade;
        lodGroup.animateCrossFading = true;
        lodGroup.RecalculateBounds();

        Debug.Log($"[LODSetup] Configured {lods.Length} LOD levels for {gameObject.name}");
    }

    private Renderer[] CreateLODRenderers(Mesh mesh, Material material)
    {
        GameObject lodGO = new GameObject($"LOD_{mesh.name}");
        lodGO.transform.SetParent(transform, false);

        MeshFilter filter = lodGO.AddComponent<MeshFilter>();
        filter.sharedMesh = mesh;

        MeshRenderer renderer = lodGO.AddComponent<MeshRenderer>();
        renderer.sharedMaterial = material;
        renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off; // LOD1+ often skip shadows

        return new Renderer[] { renderer };
    }

    // Runtime LOD debugging
    private void Update()
    {
        #if UNITY_EDITOR
        LODGroup lodGroup = GetComponent<LODGroup>();
        int currentLOD = lodGroup.GetLODs().Length - 1;

        // Find active LOD level
        for (int i = 0; i < lodGroup.GetLODs().Length; i++)
        {
            if (lodGroup.GetLODs()[i].renderers[0].isVisible)
            {
                currentLOD = i;
                break;
            }
        }

        if (Time.frameCount % 60 == 0)
        {
            Debug.Log($"[{gameObject.name}] Active LOD: {currentLOD}, Distance: {Vector3.Distance(Camera.main.transform.position, transform.position):F1}");
        }
        #endif
    }
}

using UnityEngine;
using UnityEngine.Rendering;

public class OcclusionCullingSetup : MonoBehaviour
{
    [Header("Occlusion Settings")]
    [SerializeField] private bool _isOccluder = true; // Large objects that block view
    [SerializeField] private bool _isOccludee = true;  // Objects that can be hidden
    [SerializeField] private float _occlusionBoundingScale = 1.0f;

    [Header("Dynamic Occlusion")]
    [SerializeField] private bool _useDynamicOcclusion = true;
    [SerializeField] private float _occlusionUpdateInterval = 0.5f;

    private Renderer _renderer;
    private float _occlusionTimer;

    private void Awake()
    {
        _renderer = GetComponent<Renderer>();
        if (_renderer == null) return;

        // Static occlusion: Set in Inspector via Occlusion Static flag
        // This is the primary method for static geometry

        // Dynamic occlusion for moving objects
        if (_useDynamicOcclusion && _isOccludee)
        {
            // Enable dynamic occlusion culling
            _renderer.allowOcclusionWhenDynamic = true;
        }
    }

    private void Update()
    {
        if (!_useDynamicOcclusion || !_isOccludee) return;

        // Manual occlusion check for critical objects
        _occlusionTimer += Time.deltaTime;
        if (_occlusionTimer >= _occlusionUpdateInterval)
        {
            _occlusionTimer = 0f;
            CheckOcclusion();
        }
    }

    private void CheckOcclusion()
    {
        // Check if any camera can see this object's bounds
        Bounds bounds = _renderer.bounds;
        bounds.Expand(_occlusionBoundingScale);

        bool isVisible = false;
        foreach (Camera cam in Camera.allCameras)
        {
            if (cam == null) continue;

            // Frustum check first (cheap)
            if (GeometryUtility.TestPlanesAABB(GeometryUtility.CalculateFrustumPlanes(cam), bounds))
            {
                // Occlusion check (more expensive, uses baked data)
                if (!_renderer.isVisible)
                {
                    // Object is in frustum but occluded
                    continue;
                }
                isVisible = true;
                break;
            }
        }

        // Optional: Disable expensive components when occluded
        if (!isVisible && _renderer.isVisible)
        {
            // Object just became occluded
            OnBecameOccluded();
        }
        else if (isVisible && !_renderer.isVisible)
        {
            OnBecameVisible();
        }
    }

    private void OnBecameOccluded()
    {
        // Reduce update frequency for occluded objects
        // Disable particle systems, animations, AI updates
        if (TryGetComponent<ParticleSystem>(out var ps))
            ps.Pause();

        if (TryGetComponent<Animator>(out var anim))
            anim.cullingMode = AnimatorCullingMode.CullCompletely;

        Debug.Log($"[{gameObject.name}] Became occluded — reducing updates");
    }

    private void OnBecameVisible()
    {
        if (TryGetComponent<ParticleSystem>(out var ps))
            ps.Play();

        if (TryGetComponent<Animator>(out var anim))
            anim.cullingMode = AnimatorCullingMode.AlwaysAnimate;

        Debug.Log($"[{gameObject.name}] Became visible — resuming updates");
    }

    // Occlusion culling bake settings (call from editor tool)
    #if UNITY_EDITOR
    [ContextMenu("Bake Occlusion Culling")]
    private void BakeOcclusion()
    {
        UnityEditor.StaticOcclusionCulling.GenerateInBackground();
        Debug.Log("Occlusion Culling bake started in background...");
    }
    #endif
}

using UnityEngine;

public class CameraOptimization : MonoBehaviour
{
    [Header("Layer Culling Distances")]
    [SerializeField] private float _enemyCullDistance = 100f;
    [SerializeField] private float _propCullDistance = 50f;
    [SerializeField] private float _decorationCullDistance = 30f;
    [SerializeField] private float _particleCullDistance = 20f;

    [Header("Camera Settings")]
    [SerializeField] private float _farClipPlane = 500f;
    [SerializeField] private bool _useOcclusionCulling = true;
    [SerializeField] private bool _allowHDR = false; // Disable if not needed
    [SerializeField] private bool _allowMSAA = false; // Disable if not needed

    private Camera _camera;

    private void Awake()
    {
        _camera = GetComponent<Camera>();

        // Set far clip plane
        _camera.farClipPlane = _farClipPlane;

        // Enable occlusion culling
        _camera.useOcclusionCulling = _useOcclusionCulling;

        // Disable expensive features if not needed
        _camera.allowHDR = _allowHDR;
        _camera.allowMSAA = _allowMSAA;

        // Layer-specific culling distances
        // Objects on 'Enemy' layer culled at 100m, 'Decoration' at 30m
        float[] distances = new float[32]; // 32 layers
        distances[LayerMask.NameToLayer("Enemy")] = _enemyCullDistance;
        distances[LayerMask.NameToLayer("Props")] = _propCullDistance;
        distances[LayerMask.NameToLayer("Decoration")] = _decorationCullDistance;
        distances[LayerMask.NameToLayer("Particles")] = _particleCullDistance;
        _camera.layerCullDistances = distances;
        _camera.layerCullSpherical = true; // Use spherical distance (more accurate)

        // Reduce rendering path overhead
        _camera.renderingPath = RenderingPath.Forward; // Use Deferred only if needed

        // Disable unnecessary camera events
        _camera.depthTextureMode = DepthTextureMode.None; // Disable if not using depth-based effects
    }

    // Multi-camera optimization (e.g., split-screen, security cameras)
    [Header("Multi-Camera")]
    [SerializeField] private Camera[] _secondaryCameras;
    [SerializeField] private float _secondaryCameraUpdateRate = 10f; // 10 FPS for security cams

    private float _secondaryTimer;
    private RenderTexture _securityCamTexture;

    private void Update()
    {
        // Update secondary cameras at reduced rate
        _secondaryTimer += Time.deltaTime;
        if (_secondaryTimer >= 1f / _secondaryCameraUpdateRate)
        {
            _secondaryTimer = 0f;
            RenderSecondaryCameras();
        }
    }

    private void RenderSecondaryCameras()
    {
        foreach (var cam in _secondaryCameras)
        {
            if (cam == null) continue;
            cam.Render(); // Manual render, not every frame
        }
    }

    // LOD bias: Reduce detail when FPS drops
    [Header("Adaptive Quality")]
    [SerializeField] private float _targetFPS = 60f;

    private void LateUpdate()
    {
        float currentFPS = 1f / Time.unscaledDeltaTime;

        if (currentFPS < _targetFPS - 10f)
        {
            // Reduce LOD bias (switches to lower LODs sooner)
            QualitySettings.lodBias = Mathf.Max(0.5f, QualitySettings.lodBias - 0.1f);
        }
        else if (currentFPS > _targetFPS + 10f)
        {
            // Increase LOD bias (higher detail when FPS is good)
            QualitySettings.lodBias = Mathf.Min(2f, QualitySettings.lodBias + 0.05f);
        }
    }
}

using UnityEngine;

public class PhysicsOptimization : MonoBehaviour
{
    [Header("Timestep Configuration")]
    [SerializeField, Tooltip("Physics updates per second. 50 for standard, 30 for casual, 100 for precise")]
    private float _fixedTimestep = 0.02f; // 50 Hz

    [Header("Maximum Allowed Timestep")]
    [SerializeField, Tooltip("Cap physics catch-up to prevent spiral of death")]
    private float _maxAllowedTimestep = 0.1f; // Max 5 physics steps per frame

    [Header("Adaptive Physics")]
    [SerializeField] private bool _useAdaptiveTimestep = true;
    [SerializeField] private float _lowFPSThreshold = 30f;
    [SerializeField] private float _highFPSThreshold = 55f;

    private void Awake()
    {
        // Set fixed timestep
        Time.fixedDeltaTime = _fixedTimestep;
        Time.maximumAllowedTimestep = _maxAllowedTimestep;

        Debug.Log($"[PhysicsOptimization] Fixed Timestep: {Time.fixedDeltaTime}s ({1f/Time.fixedDeltaTime:F0} Hz)");
        Debug.Log($"[PhysicsOptimization] Max Allowed Timestep: {Time.maximumAllowedTimestep}s");
    }

    private void Update()
    {
        if (!_useAdaptiveTimestep) return;

        // Adaptive timestep: reduce physics rate when FPS drops
        float currentFPS = 1f / Time.unscaledDeltaTime;

        if (currentFPS < _lowFPSThreshold && Time.fixedDeltaTime < 0.03f)
        {
            // FPS is low — reduce physics frequency to save CPU
            Time.fixedDeltaTime = 0.03f; // 33 Hz
            Debug.LogWarning($"[PhysicsOptimization] Reduced physics to 33 Hz due to low FPS ({currentFPS:F0})");
        }
        else if (currentFPS > _highFPSThreshold && Time.fixedDeltaTime > 0.02f)
        {
            // FPS recovered — restore standard physics
            Time.fixedDeltaTime = 0.02f; // 50 Hz
            Debug.Log($"[PhysicsOptimization] Restored physics to 50 Hz (FPS: {currentFPS:F0})");
        }
    }

    // ANTI-PATTERN: Non-physics logic in FixedUpdate
    // private void FixedUpdate()
    // {
    //     // BAD: Input handling, animation updates, UI logic
    //     // These should be in Update()!
    //     if (Input.GetButton("Jump")) { /* ... */ } // Input is frame-rate dependent!
    // }

    // GOOD: Physics-only in FixedUpdate
    private void FixedUpdate()
    {
        // Only physics-related code here
        ApplyBuoyancy();
        ApplyDrag();
    }

    private void ApplyBuoyancy()
    {
        // Water buoyancy physics
        if (TryGetComponent<Rigidbody>(out var rb))
        {
            float depth = CalculateWaterDepth(transform.position);
            if (depth > 0)
            {
                rb.AddForce(Vector3.up * depth * 10f, ForceMode.Acceleration);
            }
        }
    }

    private void ApplyDrag()
    {
        if (TryGetComponent<Rigidbody>(out var rb))
        {
            rb.velocity *= 0.99f; // 1% drag per physics tick
        }
    }

    private float CalculateWaterDepth(Vector3 position)
    {
        // Simplified water depth check
        return Mathf.Max(0, 5f - position.y);
    }
}

