public class ColliderOptimizer : MonoBehaviour
{
    [Header("Collider Setup")]
    [SerializeField] private ColliderType _preferredCollider = ColliderType.CompoundPrimitives;
    [SerializeField] private bool _isTrigger = false;
    [SerializeField] private PhysicMaterial _physicsMaterial;

    public enum ColliderType
    {
        Sphere,      // Fastest: distance check only
        Box,         // Fast: 6 plane checks
        Capsule,     // Fast: good for characters
        Compound,    // Multiple primitives = best approximation
        Mesh,        // SLOW: per-triangle, avoid for dynamic objects
        Terrain      // Specialized: heightmap-based
    }

    private void Awake()
    {
        SetupOptimalCollider();
    }

    private void SetupOptimalCollider()
    {
        // Remove existing colliders
        foreach (var col in GetComponents<Collider>())
        {
            Destroy(col);
        }

        switch (_preferredCollider)
        {
            case ColliderType.Sphere:
                var sphere = gameObject.AddComponent<SphereCollider>();
                sphere.radius = 0.5f;
                sphere.isTrigger = _isTrigger;
                sphere.material = _physicsMaterial;
                break;

            case ColliderType.Box:
                var box = gameObject.AddComponent<BoxCollider>();
                box.size = new Vector3(1, 2, 1);
                box.isTrigger = _isTrigger;
                box.material = _physicsMaterial;
                break;

            case ColliderType.Capsule:
                var capsule = gameObject.AddComponent<CapsuleCollider>();
                capsule.height = 2f;
                capsule.radius = 0.5f;
                capsule.isTrigger = _isTrigger;
                capsule.material = _physicsMaterial;
                break;

            case ColliderType.Compound:
                SetupCompoundCollider();
                break;

            case ColliderType.Mesh:
                // WARNING: Only for static objects or convex approximation
                var meshCol = gameObject.AddComponent<MeshCollider>();
                meshCol.convex = true; // Required for dynamic objects
                meshCol.isTrigger = _isTrigger;
                // Non-convex mesh colliders cannot collide with other non-convex mesh colliders!
                break;
        }
    }

    private void SetupCompoundCollider()
    {
        // Approximate a humanoid with 3 primitive colliders
        // Torso (box)
        GameObject torso = new GameObject("TorsoCollider");
        torso.transform.SetParent(transform, false);
        torso.transform.localPosition = new Vector3(0, 1, 0);
        var torsoBox = torso.AddComponent<BoxCollider>();
        torsoBox.size = new Vector3(0.6f, 0.9f, 0.4f);
        torsoBox.isTrigger = _isTrigger;

        // Head (sphere)
        GameObject head = new GameObject("HeadCollider");
        head.transform.SetParent(transform, false);
        head.transform.localPosition = new Vector3(0, 1.7f, 0);
        var headSphere = head.AddComponent<SphereCollider>();
        headSphere.radius = 0.2f;
        headSphere.isTrigger = _isTrigger;

        // Legs (capsule)
        GameObject legs = new GameObject("LegsCollider");
        legs.transform.SetParent(transform, false);
        legs.transform.localPosition = new Vector3(0, 0.4f, 0);
        var legsCapsule = legs.AddComponent<CapsuleCollider>();
        legsCapsule.height = 0.8f;
        legsCapsule.radius = 0.25f;
        legsCapsule.isTrigger = _isTrigger;

        Debug.Log($"[ColliderOptimizer] Setup compound collider with 3 primitives for {gameObject.name}");
    }

    // Performance comparison
    private void LogColliderPerformance()
    {
        // Approximate collision check costs (relative):
        // Sphere: 1x (distance check)
        // Box: 2x (6 plane checks, early exit)
        // Capsule: 3x (line segment + radius)
        // Convex Mesh: 10-50x (GJK/EPA algorithm)
        // Non-convex Mesh: 100-1000x (per-triangle checks)

        Debug.Log("Collider Performance (fastest to slowest):");
        Debug.Log("1. SphereCollider (1x)");
        Debug.Log("2. BoxCollider (2x)");
        Debug.Log("3. CapsuleCollider (3x)");
        Debug.Log("4. Convex MeshCollider (10-50x)");
