using UnityEngine;

public class CollisionMatrixSetup : MonoBehaviour
{
    [Header("Layer Configuration")]
    [SerializeField] private bool _enableEnemyEnemyCollision = false;
    [SerializeField] private bool _enableEnemyProjectileCollision = true;
    [SerializeField] private bool _enablePlayerPickupCollision = true;
    [SerializeField] private bool _enableDecorationPhysics = false;

    private void Awake()
    {
        SetupCollisionMatrix();
    }

    private void SetupCollisionMatrix()
    {
        // Get layer indices
        int enemyLayer = LayerMask.NameToLayer("Enemy");
        int playerLayer = LayerMask.NameToLayer("Player");
        int projectileLayer = LayerMask.NameToLayer("Projectile");
        int pickupLayer = LayerMask.NameToLayer("Pickup");
        int decorationLayer = LayerMask.NameToLayer("Decoration");
        int terrainLayer = LayerMask.NameToLayer("Terrain");
        int uiLayer = LayerMask.NameToLayer("UI");

        // Disable all collisions first, then enable only needed ones
        // (Alternative: Use Project Settings → Physics → Layer Collision Matrix)

        // Enemy layer: Collides with Player, Projectile, Terrain only
        Physics.IgnoreLayerCollision(enemyLayer, enemyLayer, !_enableEnemyEnemyCollision);
        Physics.IgnoreLayerCollision(enemyLayer, playerLayer, false); // Enable
        Physics.IgnoreLayerCollision(enemyLayer, projectileLayer, !_enableEnemyProjectileCollision);
        Physics.IgnoreLayerCollision(enemyLayer, pickupLayer, true); // Disable
        Physics.IgnoreLayerCollision(enemyLayer, decorationLayer, true); // Disable
        Physics.IgnoreLayerCollision(enemyLayer, terrainLayer, false); // Enable
        Physics.IgnoreLayerCollision(enemyLayer, uiLayer, true); // Disable

        // Player layer: Collides with Enemy, Pickup, Terrain
        Physics.IgnoreLayerCollision(playerLayer, pickupLayer, !_enablePlayerPickupCollision);
        Physics.IgnoreLayerCollision(playerLayer, projectileLayer, true); // Player bullets don't hit player
        Physics.IgnoreLayerCollision(playerLayer, uiLayer, true); // Disable

        // Projectile layer: Collides with Enemy, Terrain only
        Physics.IgnoreLayerCollision(projectileLayer, projectileLayer, true); // Bullets don't collide
        Physics.IgnoreLayerCollision(projectileLayer, pickupLayer, true);
        Physics.IgnoreLayerCollision(projectileLayer, decorationLayer, true);

        // Decoration: No physics interactions
        Physics.IgnoreLayerCollision(decorationLayer, decorationLayer, !_enableDecorationPhysics);
        Physics.IgnoreLayerCollision(decorationLayer, terrainLayer, true);

        // UI: Completely isolated
        Physics.IgnoreLayerCollision(uiLayer, uiLayer, true);

        Debug.Log("[CollisionMatrixSetup] Layer collision matrix configured");
        LogCollisionPairs();
    }

    private void LogCollisionPairs()
    {
        int totalLayers = 32;
        int activePairs = 0;
        int maxPairs = 0;

        for (int i = 0; i < totalLayers; i++)
        {
            for (int j = i; j < totalLayers; j++)
            {
                maxPairs++;
                if (!Physics.GetIgnoreLayerCollision(i, j))
                {
                    activePairs++;
                }
            }
        }

        Debug.Log($"[CollisionMatrixSetup] Active collision pairs: {activePairs}/{maxPairs} ({100f*activePairs/maxPairs:F1}%)");
    }

    // Runtime query: Which layers does a specific layer collide with?
    public static LayerMask GetCollisionMask(int layer)
    {
        int mask = 0;
        for (int i = 0; i < 32; i++)
        {
            if (!Physics.GetIgnoreLayerCollision(layer, i))
            {
                mask |= 1 << i;
            }
        }
        return mask;
    }
}

