public class NonAllocPhysics : MonoBehaviour
{
    [Header("Raycast Settings")]
    [SerializeField] private float _raycastRange = 100f;
    [SerializeField] private LayerMask _enemyLayer;
    [SerializeField] private LayerMask _terrainLayer;

    [Header("Pre-Allocated Buffers")]
    [SerializeField] private int _maxRaycastHits = 10;
    [SerializeField] private int _maxOverlapHits = 20;

    // Pre-allocated arrays — zero allocation during gameplay
    private RaycastHit[] _raycastBuffer;
    private Collider[] _overlapBuffer;
    private RaycastHit[] _sphereCastBuffer;

    private void Awake()
    {
        // Allocate once, reuse forever
        _raycastBuffer = new RaycastHit[_maxRaycastHits];
        _overlapBuffer = new Collider[_maxOverlapHits];
        _sphereCastBuffer = new RaycastHit[_maxRaycastHits];

        Debug.Log($"[NonAllocPhysics] Buffers allocated: Raycast={_maxRaycastHits}, Overlap={_maxOverlapHits}");
    }

    // WEAPON RAYCAST: Single hit (most common)
    public bool FireWeaponRay(Vector3 origin, Vector3 direction, out RaycastHit hit)
    {
        // Single raycast — no allocation even without NonAlloc
        if (Physics.Raycast(origin, direction, out hit, _raycastRange, _enemyLayer))
        {
            Debug.DrawLine(origin, hit.point, Color.red, 0.1f);
            return true;
        }
        return false;
    }

    // PENETRATION RAYCAST: Multiple hits (sniper through walls)
    public int FirePenetratingRay(Vector3 origin, Vector3 direction)
    {
        // BAD: Physics.RaycastAll allocates new array!
        // RaycastHit[] hits = Physics.RaycastAll(origin, direction, _raycastRange);

        // GOOD: RaycastNonAlloc writes into pre-allocated buffer
        int hitCount = Physics.RaycastNonAlloc(
            origin, 
            direction, 
            _raycastBuffer, 
            _raycastRange, 
            _enemyLayer | _terrainLayer
        );

        for (int i = 0; i < hitCount; i++)
        {
            ProcessHit(_raycastBuffer[i]);
            Debug.DrawLine(
                i == 0 ? origin : _raycastBuffer[i-1].point,
                _raycastBuffer[i].point,
                Color.red,
                0.5f
            );
        }

        return hitCount;
    }

    // AREA DETECTION: OverlapSphere for explosions
    public void DetonateExplosion(Vector3 center, float radius, float damage)
    {
        // BAD: Collider[] hits = Physics.OverlapSphere(center, radius); // Allocates!

        // GOOD: OverlapSphereNonAlloc
        int hitCount = Physics.OverlapSphereNonAlloc(
            center, 
            radius, 
            _overlapBuffer, 
            _enemyLayer
        );

        for (int i = 0; i < hitCount; i++)
        {
            Collider hit = _overlapBuffer[i];
            if (hit.TryGetComponent<IDamageable>(out var target))
            {
                float distance = Vector3.Distance(center, hit.transform.position);
                float falloff = 1f - (distance / radius);
                target.TakeDamage(damage * falloff);
            }
        }

        // Visual debug
        Debug.DrawRay(center, Vector3.up * radius, Color.orange, 1f);
    }

    // SWEEP CHECK: CapsuleCast for character movement prediction
    public bool CanMoveTo(Vector3 from, Vector3 to, float radius, float height)
    {
        Vector3 direction = to - from;
        float distance = direction.magnitude;
        direction.Normalize();

        // CapsuleCastNonAlloc: Check if path is clear
        int hitCount = Physics.CapsuleCastNonAlloc(
            from + Vector3.up * radius,      // Bottom sphere center
            from + Vector3.up * (height - radius), // Top sphere center
            radius,
            direction,
            _sphereCastBuffer,
            distance,
            _terrainLayer
        );

        return hitCount == 0; // True if no obstacles
    }

    // BOX CHECK: Melee attack area
    public void PerformMeleeAttack(Vector3 center, Vector3 halfExtents, Quaternion orientation, float damage)
    {
        int hitCount = Physics.OverlapBoxNonAlloc(
            center,
            halfExtents,
            _overlapBuffer,
            orientation,
            _enemyLayer
        );

        for (int i = 0; i < hitCount; i++)
        {
            if (_overlapBuffer[i].TryGetComponent<IDamageable>(out var target))
            {
                target.TakeDamage(damage);
            }
        }
    }

    private void ProcessHit(RaycastHit hit)
    {
        // Apply damage, spawn impact effect, etc.
        Debug.Log($"Hit: {hit.collider.name} at {hit.point}, distance: {hit.distance:F2}");
    }
}

