public class RaycastOptimizer : MonoBehaviour
{
    [Header("Optimized Raycast Settings")]
    [SerializeField] private LayerMask _shootableLayers;
    [SerializeField] private float _maxWeaponRange = 50f;
    [SerializeField] private QueryTriggerInteraction _triggerInteraction = QueryTriggerInteraction.Ignore;

    // Cached layer masks for specific scenarios
    private static readonly LayerMask LAYER_ENEMY = LayerMask.GetMask("Enemy");
    private static readonly LayerMask LAYER_TERRAIN = LayerMask.GetMask("Terrain");
    private static readonly LayerMask LAYER_ENEMY_AND_TERRAIN = LayerMask.GetMask("Enemy", "Terrain");

    // Pre-allocated buffer for multi-hit queries
    private readonly RaycastHit[] _hitBuffer = new RaycastHit[5];

    // OPTIMIZED: Weapon fire with early exit
    public bool FireWeaponOptimized(Vector3 origin, Vector3 direction)
    {
        // 1. Short range first — most likely to hit, early exit saves CPU
        if (Physics.Raycast(origin, direction, out RaycastHit hit, 10f, LAYER_ENEMY, _triggerInteraction))
        {
            // Hit enemy at close range — immediate damage
            ApplyDamage(hit.collider, 100f);
            return true;
        }

        // 2. Medium range — terrain and enemies
        if (Physics.Raycast(origin, direction, out hit, _maxWeaponRange, LAYER_ENEMY_AND_TERRAIN, _triggerInteraction))
        {
            if (hit.collider.gameObject.layer == LayerMask.NameToLayer("Enemy"))
            {
                ApplyDamage(hit.collider, 50f); // Reduced damage at distance
            }
            else
            {
                SpawnImpactEffect(hit.point, hit.normal); // Terrain hit
            }
            return true;
        }

        return false; // Missed everything
    }

    // OPTIMIZED: Line of sight check (frequent AI query)
    public bool HasLineOfSight(Vector3 from, Vector3 to)
    {
        Vector3 direction = to - from;
        float distance = direction.magnitude;
        direction.Normalize();

        // Only check terrain layer — ignore enemies, pickups, particles
        // QueryTriggerInteraction.Ignore prevents false positives from trigger zones
        return !Physics.Raycast(from, direction, distance, LAYER_TERRAIN, _triggerInteraction);
    }

    // OPTIMIZED: Multi-target sweep (shotgun, explosion shrapnel)
    public void ShotgunBlast(Vector3 origin, Vector3 direction, float spreadAngle, int pelletCount)
    {
        for (int i = 0; i < pelletCount; i++)
        {
            // Calculate spread direction
            Quaternion spread = Quaternion.Euler(
                Random.Range(-spreadAngle, spreadAngle),
                Random.Range(-spreadAngle, spreadAngle),
                0
            );
            Vector3 pelletDir = spread * direction;

            // Single raycast per pellet — no allocation
            if (Physics.Raycast(origin, pelletDir, out RaycastHit hit, _maxWeaponRange, _shootableLayers, _triggerInteraction))
            {
                ApplyDamage(hit.collider, 8f); // Per-pellet damage
            }
        }
    }

    // OPTIMIZED: Spatial query batching (find all enemies in cone)
    public int ConeCast(Vector3 origin, Vector3 direction, float coneAngle, float maxDistance)
    {
        // Use OverlapSphere first (broad phase) — cheaper than many raycasts
        int hitCount = Physics.OverlapSphereNonAlloc(origin, maxDistance, _overlapBuffer, LAYER_ENEMY);

        int validHits = 0;
        for (int i = 0; i < hitCount; i++)
        {
            Vector3 toTarget = (_overlapBuffer[i].transform.position - origin).normalized;
            float angle = Vector3.Angle(direction, toTarget);

            if (angle < coneAngle)
            {
                // Narrow phase: raycast to confirm visibility
                if (HasLineOfSight(origin, _overlapBuffer[i].transform.position))
                {
                    validHits++;
                }
            }
        }

        return validHits;
    }

    // Cache for overlap buffer
    private readonly Collider[] _overlapBuffer = new Collider[20];

    private void ApplyDamage(Collider target, float damage)
    {
        if (target.TryGetComponent<IDamageable>(out var damageable))
        {
            damageable.TakeDamage(damage);
        }
    }

    private void SpawnImpactEffect(Vector3 point, Vector3 normal)
    {
        // Spawn impact VFX
    }
}

