            if (rb.interpolation == RigidbodyInterpolation.Interpolate)
            {
                // Unity handles this automatically for interpolated rigidbodies
                continue;
            }

            // Manual interpolation for non-interpolated bodies
            // Store previous position in a custom component and lerp
        }
    }

    public void SetBulletTime(bool active)
    {
        _timeScale = active ? 0.2f : 1f; // 20% speed for bullet time

        if (!active)
        {
