[RequireComponent(typeof(Rigidbody))]
public class VisibilityCulledPhysics : MonoBehaviour
{
    [Header("Culling Settings")]
    [SerializeField] private float _visibleUpdateRate = 50f; // Hz when visible
    [SerializeField] private float _occludedUpdateRate = 10f; // Hz when behind wall
    [SerializeField] private float _offscreenUpdateRate = 0f;  // Hz when off-screen (paused)
    [SerializeField] private float _wakeDistance = 20f;

    [Header("References")]
    [SerializeField] private Renderer _renderer;

    private Rigidbody _rb;
    private float _physicsTimer;
    private float _currentTimestep;
    private bool _wasVisible;
    private Transform _playerTransform;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody>();
        _renderer = GetComponent<Renderer>();
        _playerTransform = Camera.main?.transform;

        // Start with standard physics
        _currentTimestep = 1f / _visibleUpdateRate;
    }

    private void Update()
    {
        if (_playerTransform == null) return;

        // Determine visibility state
        bool isVisible = _renderer.isVisible;
        bool isNear = Vector3.Distance(transform.position, _playerTransform.position) < _wakeDistance;

        // State machine for physics update rate
        if (!isVisible && !isNear)
        {
            // Off-screen and far: completely pause physics
            SetPhysicsRate(_offscreenUpdateRate);
            _rb.Sleep(); // Put rigidbody to sleep
        }
        else if (!isVisible && isNear)
        {
            // Near but occluded: reduced rate
            SetPhysicsRate(_occludedUpdateRate);
        }
        else
        {
            // Visible: full rate
            SetPhysicsRate(_visibleUpdateRate);
            if (_rb.IsSleeping()) _rb.WakeUp();
        }

        _wasVisible = isVisible;
    }

    private void SetPhysicsRate(float rateHz)
    {
        if (rateHz <= 0)
        {
            // Pause physics for this object
            _rb.isKinematic = true;
            _currentTimestep = float.MaxValue;
            return;
        }

        _rb.isKinematic = false;
        _currentTimestep = 1f / rateHz;
    }

    // Custom physics step based on visibility
    private void FixedUpdate()
    {
        if (_currentTimestep == float.MaxValue) return;

        _physicsTimer += Time.fixedDeltaTime;
        if (_physicsTimer >= _currentTimestep)
        {
            _physicsTimer -= _currentTimestep;
            PerformCustomPhysicsStep();
        }
    }

    private void PerformCustomPhysicsStep()
    {
        // Reduced-rate physics logic
        // e.g., simplified AI, reduced force calculations
        ApplyGravity();
        ApplyDrag();
    }

    private void ApplyGravity()
    {
        if (!_rb.isKinematic)
        {
            _rb.AddForce(Physics.gravity * _rb.mass, ForceMode.Force);
        }
    }

    private void ApplyDrag()
    {
        if (!_rb.isKinematic)
        {
            _rb.velocity *= 0.99f;
        }
    }

    // Event-driven wake-up when player approaches
    private void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Player"))
        {
            SetPhysicsRate(_visibleUpdateRate);
            _rb.WakeUp();
        }
    }
}

