        _lodGroup = GetComponent<LODGroup>();

        // Validate colliders
        Debug.Assert(_lod0Collider != null, "LOD0 collider required", this);

        // Start with LOD0
        SetLODPhysics(0);
    }

    private void Update()
    {
        // Check active LOD level
        int activeLOD = GetActiveLODLevel();
        if (activeLOD != _currentLOD)
        {
            SetLODPhysics(activeLOD);
            _currentLOD = activeLOD;
        }
    }

    private int GetActiveLODLevel()
    {
        // Get the currently active LOD level from the LODGroup
        LOD[] lods = _lodGroup.GetLODs();
        for (int i = 0; i < lods.Length; i++)
        {
            if (lods[i].renderers.Length > 0 && lods[i].renderers[0].isVisible)
            {
                return i;
            }
        }
        return lods.Length - 1; // Culled / lowest LOD
    }

    private void SetLODPhysics(int lodLevel)
    {
        // Disable all colliders first
        if (_lod0Collider != null) _lod0Collider.enabled = false;
        if (_lod1Collider != null) _lod1Collider.enabled = false;
        if (_lod2Collider != null) _lod2Collider.enabled = false;

        switch (lodLevel)
        {
            case 0: // Close: precise collision
                if (_lod0Collider != null) _lod0Collider.enabled = true;
                Debug.Log($"[{gameObject.name}] Physics: LOD0 (precise)");
                break;

            case 1: // Medium: simplified collision
                if (_lod1Collider != null) _lod1Collider.enabled = true;
                else if (_lod0Collider != null) _lod0Collider.enabled = true; // Fallback
                Debug.Log($"[{gameObject.name}] Physics: LOD1 (simplified)");
                break;

            case 2: // Far: very simple collision
                if (_lod2Collider != null) _lod2Collider.enabled = true;
                else if (_lod1Collider != null) _lod1Collider.enabled = true;
                else if (_lod0Collider != null) _lod0Collider.enabled = true;
                Debug.Log($"[{gameObject.name}] Physics: LOD2 (minimal)");
                break;

            default: // Culled: disable collision
                if (_disableCollisionAtLOD3)
                {
                    Debug.Log($"[{gameObject.name}] Physics: Disabled (culled)");
                }
                break;
        }
    }

    // Performance comparison logging
    private void LogColliderComplexity()
    {
        int lod0Complexity = GetColliderComplexity(_lod0Collider);
        int lod1Complexity = GetColliderComplexity(_lod1Collider);
        int lod2Complexity = GetColliderComplexity(_lod2Collider);

        Debug.Log($"Collider complexity: LOD0={lod0Complexity}, LOD1={lod1Complexity}, LOD2={lod2Complexity}");
    }

    private int GetColliderComplexity(Collider col)
    {
        return col switch
        {
            SphereCollider => 1,
            BoxCollider => 2,
            CapsuleCollider => 3,
            MeshCollider mc => mc.convex ? 10 : 100,
            _ => 5
        };
    }
}

using UnityEngine;
using UnityEngine.Profiling;
using UnityEngine.Rendering;

public class OptimizationDashboard : MonoBehaviour
{
    [Header("Display")]
    [SerializeField] private bool _showOverlay = true;
    [SerializeField] private KeyCode _toggleKey = KeyCode.F3;

    [Header("Alert Thresholds")]
    [SerializeField] private float _maxDrawCalls = 200;
    [SerializeField] private float _maxPhysicsTime = 3f; // ms
    [SerializeField] private float _maxGCTime = 5f; // ms

    private float _deltaTime;
    private float _fps;
    private int _drawCalls;
    private float _physicsTime;
    private float _renderTime;
    private int _activeRigidbodies;
    private long _gcMemory;

    private void Update()
    {
        if (Input.GetKeyDown(_toggleKey))
        {
            _showOverlay = !_showOverlay;
        }

        // Gather metrics
        _deltaTime = Time.unscaledDeltaTime;
        _fps = 1f / _deltaTime;
        _drawCalls = UnityStats.drawCalls;
        _physicsTime = Profiler.GetLastFrameCpuTime() * 1000f; // Approximate
        _renderTime = Profiler.GetLastFrameGpuTime() * 1000f;
        _activeRigidbodies = CountActiveRigidbodies();
        _gcMemory = System.GC.GetTotalMemory(false);
    }

    private void OnGUI()
    {
        if (!_showOverlay) return;

        GUILayout.BeginArea(new Rect(10, 10, 300, 250), "Optimization Dashboard", "box");

        // FPS with color coding
        GUI.color = _fps < 30 ? Color.red : _fps < 55 ? Color.yellow : Color.green;
        GUILayout.Label($"FPS: {_fps:F0} ({_deltaTime*1000:F1}ms)");
        GUI.color = Color.white;

        // Draw Calls
        GUI.color = _drawCalls > _maxDrawCalls ? Color.red : Color.green;
        GUILayout.Label($"Draw Calls: {_drawCalls} / {_maxDrawCalls}");
        GUI.color = Color.white;

        // Physics
        GUI.color = _physicsTime > _maxPhysicsTime ? Color.red : Color.green;
        GUILayout.Label($"Physics: {_physicsTime:F2}ms / {_maxPhysicsTime:F0}ms");
        GUI.color = Color.white;

        // Rendering
        GUILayout.Label($"Render: {_renderTime:F2}ms");

        // Rigidbodies
        GUILayout.Label($"Active Rigidbodies: {_activeRigidbodies}");

        // Memory
        GUILayout.Label($"GC Memory: {_gcMemory/1024/1024:F1}MB");

        // Auto-tuning suggestion
        if (_fps < 30)
        {
            GUI.color = Color.red;
            GUILayout.Label("WARNING: Auto-reducing quality...");
            GUI.color = Color.white;
            ReduceQuality();
        }

        GUILayout.EndArea();
    }

    private int CountActiveRigidbodies()
    {
        int count = 0;
        foreach (var rb in FindObjectsOfType<Rigidbody>())
        {
            if (!rb.IsSleeping()) count++;
        }
        return count;
    }

    private void ReduceQuality()
    {
        // Auto-reduce quality when FPS drops
        if (QualitySettings.GetQualityLevel() > 0)
        {
            QualitySettings.DecreaseLevel();
        }

        // Reduce shadow distance
        QualitySettings.shadowDistance = Mathf.Max(10f, QualitySettings.shadowDistance - 5f);

        // Reduce LOD bias (switch to lower LODs sooner)
        QualitySettings.lodBias = Mathf.Max(0.5f, QualitySettings.lodBias - 0.2f);
    }
}

using Unity.Entities;
using Unity.Mathematics;
using Unity.Transforms;
using UnityEngine;

// COMPONENT: Pure data struct (no methods, no logic)
// IComponentData marks this as an ECS component
public struct MovementData : IComponentData
{
    public float3 Velocity;
    public float Speed;
    public float3 TargetPosition;
}

public struct HealthData : IComponentData
{
    public float CurrentHealth;
    public float MaxHealth;
    public bool IsAlive;
}

public struct EnemyTag : IComponentData { } // Tag component (zero-size marker)

// SYSTEM: Logic that processes entities with specific components
public partial class MovementSystem : SystemBase
{
    protected override void OnUpdate()
    {
        float deltaTime = Time.DeltaTime;

        // Query: Process all entities with MovementData AND LocalTransform
        // BurstCompile + JobEntity = automatic parallel job generation
        Entities
            .ForEach((ref LocalTransform transform, in MovementData movement) =>
            {
                // 'ref' = read-write access to transform
                // 'in' = read-only access to movement (optimization hint)

                float3 direction = movement.TargetPosition - transform.Position;
                float distance = math.length(direction);

                if (distance > 0.1f)
                {
                    direction = math.normalize(direction);
                    transform.Position += direction * movement.Speed * deltaTime;
                    transform.Rotation = quaternion.LookRotation(direction, math.up());
                }
            })
            .ScheduleParallel(); // Run on all worker threads
    }
}

// SYSTEM: Health processing with tag filtering
public partial class HealthSystem : SystemBase
{
    protected override void OnUpdate()
    {
        // Query: Only entities with HealthData AND EnemyTag
        Entities
            .WithAll<EnemyTag>()
            .ForEach((ref HealthData health) =>
            {
                if (health.CurrentHealth <= 0 && health.IsAlive)
                {
                    health.IsAlive = false;
                    // In real code: raise death event, spawn effects
                }
            })
            .ScheduleParallel();
    }
}

