using Unity.Entities;
using Unity.Mathematics;
using Unity.Transforms;
using Unity.Collections;
using Unity.Burst;

public partial class SpawnSystem : SystemBase
{
    private EntityQuery _spawnRequestQuery;
    private Entity _bulletPrefab;

    protected override void OnCreate()
    {
        // Query entities that want to spawn something
        _spawnRequestQuery = GetEntityQuery(typeof(SpawnRequestData));
    }

    protected override void OnUpdate()
    {
        // Create command buffer (records structural changes)
        EntityCommandBuffer ecb = new EntityCommandBuffer(Allocator.TempJob);

        // Get prefab entity (baked at edit time)
        if (_bulletPrefab == Entity.Null)
        {
            _bulletPrefab = GetSingletonEntity<BulletPrefabData>();
        }

        // Process spawn requests
        Entities
            .WithAll<SpawnRequestData>()
            .ForEach((Entity entity, in LocalTransform transform, in SpawnRequestData request) =>
            {
                // Record spawn command (does NOT execute immediately)
                Entity newBullet = ecb.Instantiate(_bulletPrefab);

                ecb.SetComponent(newBullet, new LocalTransform
                {
                    Position = transform.Position,
                    Rotation = quaternion.LookRotation(request.Direction, math.up()),
                    Scale = 1f
                });

                ecb.SetComponent(newBullet, new MovementData
                {
                    Velocity = request.Direction * request.Speed,
                    Speed = request.Speed,
                    TargetPosition = transform.Position + request.Direction * 100f
                });

                // Remove spawn request (another structural change)
                ecb.RemoveComponent<SpawnRequestData>(entity);
            })
            .Schedule();

        // Apply all recorded commands AFTER the job completes
        Dependency.Complete();
        ecb.Playback(EntityManager);
        ecb.Dispose();
    }
}

// COMPONENT: Spawn request (processed then removed)
public struct SpawnRequestData : IComponentData
{
    public float3 Direction;
    public float Speed;
    public Entity Prefab;
}

// COMPONENT: Bullet prefab marker
public struct BulletPrefabData : IComponentData { }

// SYSTEM: Destroy entities with zero health
public partial class DestroySystem : SystemBase
{
    protected override void OnUpdate()
    {
        EntityCommandBuffer ecb = new EntityCommandBuffer(Allocator.TempJob);

        Entities
            .WithAll<EnemyTag>()
            .ForEach((Entity entity, in HealthData health) =>
            {
                if (!health.IsAlive)
                {
                    // Record destruction (happens after job completes)
                    ecb.DestroyEntity(entity);

                    // Could also spawn death effect here
                    // ecb.Instantiate(deathEffectPrefab);
                }
            })
            .Schedule();

        Dependency.Complete();
        ecb.Playback(EntityManager);
        ecb.Dispose();
    }
}

// BURST-COMPILED SYSTEM: Maximum performance
[BurstCompile]
public partial struct BurstMovementJob : IJobEntity
{
    public float DeltaTime;

    // IJobEntity automatically generates the query and loop
    void Execute(ref LocalTransform transform, in MovementData movement)
    {
        float3 direction = movement.TargetPosition - transform.Position;
        float distance = math.length(direction);

        if (distance > 0.1f)
        {
            direction = math.normalize(direction);
            transform.Position += direction * movement.Speed * DeltaTime;
        }
    }
}

public partial class BurstMovementSystem : SystemBase
{
    protected override void OnUpdate()
    {
        new BurstMovementJob
        {
            DeltaTime = SystemAPI.Time.DeltaTime
        }.ScheduleParallel();
    }
}

