public class AddressablesManager : MonoBehaviour
{
    [Header("Asset References")]
    [SerializeField] private AssetReference _playerPrefabRef;
    [SerializeField] private AssetReference _levelMusicRef;
    [SerializeField] private List<AssetReference> _enemyPrefabRefs;

    [Header("Loaded Assets")]
    private GameObject _loadedPlayer;
    private AudioClip _loadedMusic;
    private readonly List<GameObject> _loadedEnemies = new List<GameObject>();

    private AsyncOperationHandle<GameObject> _playerHandle;
    private AsyncOperationHandle<AudioClip> _musicHandle;
    private readonly List<AsyncOperationHandle<GameObject>> _enemyHandles = new List<AsyncOperationHandle<GameObject>>();

    private async void Start()
    {
        await Addressables.InitializeAsync().Task;

        _playerHandle = Addressables.LoadAssetAsync<GameObject>(_playerPrefabRef);
        _loadedPlayer = await _playerHandle.Task;
        Instantiate(_loadedPlayer, Vector3.zero, Quaternion.identity);

        _musicHandle = Addressables.LoadAssetAsync<AudioClip>(_levelMusicRef);
        _loadedMusic = await _musicHandle.Task;
        AudioSource.PlayClipAtPoint(_loadedMusic, Camera.main.transform.position);

        await SpawnEnemyWave(10);
        Debug.Log("[AddressablesManager] All assets loaded successfully.");
    }

    private async System.Threading.Tasks.Task SpawnEnemyWave(int count)
    {
        for (int i = 0; i < count; i++)
        {
            int randomIndex = Random.Range(0, _enemyPrefabRefs.Count);
            AssetReference enemyRef = _enemyPrefabRefs[randomIndex];
            AsyncOperationHandle<GameObject> handle = Addressables.LoadAssetAsync<GameObject>(enemyRef);
            GameObject enemyPrefab = await handle.Task;
            Vector3 spawnPos = new Vector3(Random.Range(-20f, 20f), 0, Random.Range(-20f, 20f));
            GameObject enemy = Instantiate(enemyPrefab, spawnPos, Quaternion.identity);
            _loadedEnemies.Add(enemy);
            _enemyHandles.Add(handle);
        }
    }

    private void OnDestroy()
    {
        if (_playerHandle.IsValid()) Addressables.Release(_playerHandle);
        if (_musicHandle.IsValid()) Addressables.Release(_musicHandle);
        foreach (var handle in _enemyHandles)
        {
            if (handle.IsValid()) Addressables.Release(handle);
        }
        _enemyHandles.Clear();
        Debug.Log("[AddressablesManager] All assets released.");
    }

