        {
            float progress = handle.GetDownloadStatus().Percent;
            Debug.Log($"Loading {sceneKey}: {progress:P0}");
            await System.Threading.Tasks.Task.Yield();
        }
        Debug.Log($"Scene {sceneKey} loaded.");
    }
}

using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;
using System.Collections.Generic;

public class ReferenceCountedAsset<T> where T : Object
{
    private readonly AsyncOperationHandle<T> _handle;
    private int _referenceCount;

    public T Asset => _handle.Result;
    public bool IsLoaded => _handle.IsDone && _handle.Status == AsyncOperationStatus.Succeeded;

    public ReferenceCountedAsset(AsyncOperationHandle<T> handle)
    {
        _handle = handle;
        _referenceCount = 1;
    }

    public void AddReference() => _referenceCount++;

    public void ReleaseReference()
    {
        _referenceCount--;
        if (_referenceCount <= 0 && _handle.IsValid())
        {
            Addressables.Release(_handle);
            Debug.Log($"[ReferenceCountedAsset] Released {typeof(T).Name}");
        }
    }
}

public class SafeAssetPool : MonoBehaviour
{
    private readonly Dictionary<string, ReferenceCountedAsset<GameObject>> _prefabCache = new Dictionary<string, ReferenceCountedAsset<GameObject>>();
    private readonly Dictionary<GameObject, string> _instanceToKey = new Dictionary<GameObject, string>();

    public async System.Threading.Tasks.Task<GameObject> GetPrefab(string key)
    {
        if (_prefabCache.TryGetValue(key, out var cached))
        {
            cached.AddReference();
            return cached.Asset;
        }
        AsyncOperationHandle<GameObject> handle = Addressables.LoadAssetAsync<GameObject>(key);
        GameObject prefab = await handle.Task;
        var refCounted = new ReferenceCountedAsset<GameObject>(handle);
        _prefabCache[key] = refCounted;
        return prefab;
    }

    public GameObject InstantiatePrefab(string key, Vector3 position, Quaternion rotation)
    {
        if (!_prefabCache.TryGetValue(key, out var cached)) return null;
        GameObject instance = Instantiate(cached.Asset, position, rotation);
        _instanceToKey[instance] = key;
        return instance;
    }

    public void DestroyInstance(GameObject instance)
    {
        if (instance == null) return;
        if (_instanceToKey.TryGetValue(instance, out string key))
        {
            _instanceToKey.Remove(instance);
            Destroy(instance);
            if (_prefabCache.TryGetValue(key, out var cached))
            {
                cached.ReleaseReference();
            }
        }
        else
        {
            Destroy(instance);
        }
    }

    public void ClearCache()
    {
        foreach (var kvp in _prefabCache)
        {
            while (kvp.Value.IsLoaded)
            {
                kvp.Value.ReleaseReference();
            }
        }
        _prefabCache.Clear();
        _instanceToKey.Clear();
    }
}

