    #if UNITY_EDITOR
    [MenuItem("Build/Optimize Build Size")]
    public static void OptimizeBuild()
    {
        SetTextureCompression();
        SetAudioCompression();
        CleanResourcesFolder();
        PlayerSettings.SetScriptingBackend(BuildTargetGroup.Android, ScriptingImplementation.IL2CPP);
        PlayerSettings.SetManagedStrippingLevel(BuildTargetGroup.Android, ManagedStrippingLevel.High);
        Debug.Log("[BuildSizeOptimizer] Optimization complete.");
    }

    private static void SetTextureCompression()
    {
        string[] textureGuids = AssetDatabase.FindAssets("t:Texture2D", new[] { "Assets/_Project" });
        foreach (string guid in textureGuids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            TextureImporter importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer == null) continue;

            TextureImporterPlatformSettings androidSettings = importer.GetPlatformTextureSettings("Android");
            androidSettings.format = TextureImporterFormat.ASTC_6x6;
            androidSettings.overridden = true;
            importer.SetPlatformTextureSettings(androidSettings);

            TextureImporterPlatformSettings pcSettings = importer.GetPlatformTextureSettings("Standalone");
            pcSettings.format = TextureImporterFormat.DXT5;
            pcSettings.overridden = true;
            importer.SetPlatformTextureSettings(pcSettings);

            TextureImporterPlatformSettings iosSettings = importer.GetPlatformTextureSettings("iPhone");
            iosSettings.format = TextureImporterFormat.ASTC_6x6;
            iosSettings.overridden = true;
            importer.SetPlatformTextureSettings(iosSettings);

            importer.SaveAndReimport();
        }
        Debug.Log($"[BuildSizeOptimizer] Compressed {textureGuids.Length} textures");
    }

    private static void SetAudioCompression()
    {
        string[] audioGuids = AssetDatabase.FindAssets("t:AudioClip", new[] { "Assets/_Project" });
        foreach (string guid in audioGuids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            AudioImporter importer = AssetImporter.GetAtPath(path) as AudioImporter;
            if (importer == null) continue;

            AudioImporterSampleSettings settings = importer.defaultSampleSettings;
            if (path.Contains("Music") || path.Contains("Ambience"))
            {
                settings.compressionFormat = AudioCompressionFormat.Vorbis;
                settings.quality = 0.7f;
            }
            else
            {
                settings.compressionFormat = AudioCompressionFormat.ADPCM;
            }
            importer.defaultSampleSettings = settings;
            importer.SaveAndReimport();
        }
        Debug.Log($"[BuildSizeOptimizer] Compressed {audioGuids.Length} audio clips");
    }

    private static void CleanResourcesFolder()
    {
        string[] resourceGuids = AssetDatabase.FindAssets("", new[] { "Assets/Resources" });
        Debug.LogWarning($"[BuildSizeOptimizer] {resourceGuids.Length} assets in Resources folder inflate build size. Move to Addressables!");
    }
    #endif
}
